commerce-product-picker:
@if (products.length) {
  <div class="picker-table" role="listbox" aria-label="Product results">
    @for (product of products; track product.id) {
      <button class="picker-row" type="button" (click)="selected.emit(product)">
        <span class="picker-icon" aria-hidden="true">◇</span>
        <span class="picker-product"
          ><strong>{{ product.name }}</strong
          ><small
            >{{ product.sku || product.barcode || 'No SKU'
            }}{{ product.barcode && product.sku ? ' · ' + product.barcode : '' }}</small
          ></span
        >
        <span class="picker-stock"
          ><strong>{{ product.availableQuantity }} available</strong
          ><small>{{ product.stockScopeName || facilityName }}</small></span
        >
        <span class="picker-price"
          ><strong>{{ product.salePrice ?? product.price | number: '1.2-2' }}</strong
          ><small>{{ product.stockStatus }}</small></span
        >
        <span class="picker-chevron" aria-hidden="true">›</span>
      </button>
    }
  </div>
} @else if (searchActive) {
  <div class="picker-table picker-empty" role="status">
    <strong>No products found</strong>
    <small>Try a different barcode, SKU, or product name.</small>
  </div>
}
